"""Bounded owning-work read, called inside the existing authenticated Jira collection."""
import base64
from bind_native_providers import JIRA_ROOT, ProbeError
from collect_native_sources import text_content

def snapshot(cfg, call):
    if cfg.get("base_url") != JIRA_ROOT or cfg.get("project_allowlist") != ["RBO"]:
        raise ProbeError("rsc_jira_scope")
    headers = {"Authorization": "Basic " + base64.b64encode((cfg["email"]+":"+cfg["api_token"]).encode()).decode()}
    issue = call(JIRA_ROOT+"/rest/api/3/issue/RBO-34?fields=summary,description,status,updated", headers)
    if issue.get("key") != "RBO-34":
        raise ProbeError("rsc_issue_identity")
    page = call(JIRA_ROOT+"/rest/api/3/issue/RBO-34/comment?orderBy=-created&startAt=0&maxResults=50", headers)
    rows = page.get("comments")
    if not isinstance(rows, list) or page.get("startAt") != 0 or not isinstance(page.get("total"), int):
        raise ProbeError("rsc_comments_invalid")
    if len(rows) != min(50, page["total"]):
        raise ProbeError("rsc_comments_incomplete")
    fields = issue["fields"]
    comments = [{"id":str(row["id"]), "updated":row["updated"],
                 "body":text_content(row.get("body", {})),
                 "author_account_id":row.get("author", {}).get("accountId")} for row in rows]
    return {"issue_key":"RBO-34", "updated":fields["updated"], "summary":fields["summary"],
            "description":text_content(fields.get("description") or {}),
            "status":fields["status"]["name"], "comments":comments,
            "coverage":"latest_50_comments_and_current_issue", "total_comments":page["total"],
            "source_verified":True}
